#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    /* Circular queue of capacity 5 */
    long items[5];
    int head = 0;      // index of the front element
    int count = 0;     // number of elements currently stored

    if (argc < 2) {
        /* No commands supplied */
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];
        if (cmd[0] == 'E') {                     // Enqueue command, e.g. "E42"
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);
            if (endptr == cmd + 1) {            // no number after 'E'
                puts("ERR");
                continue;
            }
            if (count == 5) {                    // queue full
                puts("FULL");
                continue;
            }
            items[(head + count) % 5] = val;
            ++count;
            printf("ENQ %ld\n", val);
        }
        else if (strcmp(cmd, "D") == 0) {      // Dequeue command
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long val = items[head];
            head = (head + 1) % 5;
            --count;
            printf("DEQ %ld\n", val);
        }
        else if (strcmp(cmd, "F") == 0) {      // Front (peek) command
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            printf("FRONT %ld\n", items[head]);
        }
        else if (strcmp(cmd, "N") == 0) {      // No‑operation command (optional)
            puts("NOOP");
        }
        else {
            /* Any unrecognised command is an error */
            puts("ERR");
        }
    }
    return 0;
}
